server {
  listen 80;
  server_name limesurvey.workspace.localhost;
  resolver 127.0.0.11 valid=10s ipv6=off;
  client_max_body_size 64m;

  location / {

    if ($request_method = OPTIONS) {
      add_header Access-Control-Allow-Origin  $limesurvey_allowed_origin_workspace always;
      add_header Access-Control-Allow-Methods "GET, POST, PUT, PATCH, DELETE, OPTIONS" always;
      add_header Access-Control-Allow-Headers "*" always;
      add_header Access-Control-Max-Age       "86400" always;
      add_header Vary                         "Origin" always;
      return 204;
    }

    # Hidden before it is re-added, so an endpoint that sets its own origin header cannot end up
    # sending the two conflicting values browsers reject outright.
    proxy_hide_header Access-Control-Allow-Origin;
    add_header Access-Control-Allow-Origin $limesurvey_allowed_origin_workspace always;
    add_header Vary                        "Origin" always;

    set $upstream http://limesurvey.workspace.internal:8080;
    proxy_pass $upstream;
    proxy_http_version 1.1;
    proxy_set_header Host $host;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto $scheme;
    proxy_set_header X-Forwarded-Host $host;
    proxy_set_header X-Forwarded-Port $server_port;
    proxy_set_header Upgrade $http_upgrade;
    proxy_set_header Connection $connection_upgrade_workspace;
    proxy_buffer_size 128k;
    proxy_buffers 4 256k;
    proxy_busy_buffers_size 256k;
    proxy_read_timeout 60s;
  }
}

server {
  listen 80;
  server_name tiles.workspace.localhost;
  resolver 127.0.0.11 valid=10s ipv6=off;

  location / {

    if ($request_method = OPTIONS) {
      add_header Access-Control-Allow-Origin  "$http_origin" always;
      add_header Access-Control-Allow-Methods "GET, HEAD, OPTIONS" always;
      add_header Access-Control-Allow-Headers "*" always;
      add_header Access-Control-Max-Age       "86400" always;
      add_header Vary                         "Origin" always;
      return 204;
    }

    proxy_hide_header Access-Control-Allow-Origin;
    add_header Access-Control-Allow-Origin  "$http_origin" always;
    add_header Access-Control-Allow-Methods "GET, HEAD, OPTIONS" always;
    add_header Vary                         "Origin" always;

    proxy_set_header Accept-Encoding "";
    sub_filter_types application/json;
    sub_filter_once off;
    sub_filter 'https://tiles.swcode.io' 'http://tiles.workspace.localhost';

    proxy_ssl_server_name on;
    set $upstream https://tiles.swcode.io;
    proxy_pass $upstream;
    proxy_http_version 1.1;
    proxy_set_header Host tiles.swcode.io;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto $scheme;
    proxy_set_header X-Forwarded-Host $host;
    proxy_set_header X-Forwarded-Port $server_port;
    proxy_set_header Upgrade $http_upgrade;
    proxy_set_header Connection $connection_upgrade_workspace;
    proxy_buffer_size 128k;
    proxy_buffers 4 256k;
    proxy_busy_buffers_size 256k;
    proxy_read_timeout 60s;
  }
}
